<?php
use Hambelela\Acknowledgments\Service as S;
require_once __DIR__.'/../../shared/acknowledgments/ResponseChats.php';
$db->exec(file_get_contents(__DIR__.'/../../database/ack-response-chats.sql'));
$chat=new \Hambelela\Acknowledgments\ResponseChats($db);
$start=['operation'=>'create','employee'=>2,'request_key'=>S::uuid(),'title'=>'Stock question','message'=>'What arrived?'];
$before=count($s->listing(2)['records']);
denied(fn()=>$chat->write(3,$start),'An employee cannot initiate an owner request');
$cid=$chat->write(1,$start)['id'];
check($chat->write(1,$start)['id']===$cid&&count($chat->detail(2,$cid)['messages'])===1,'Retry sends only one thread and opening message');
$other=$chat->write(1,array_replace($start,['request_key'=>S::uuid()]))['id'];
denied(fn()=>$chat->detail(3,$cid),'Colleagues cannot open private response threads');
denied(fn()=>$chat->detail(5,$cid),'Other admins cannot open private response threads');
check(count($chat->listing(3))===0&&$chat->prompt(2)['count']===2,'Only recipient sees both questions');
$act=fn($op,$rev)=>['operation'=>$op,'id'=>$cid,'revision'=>$rev];
denied(fn()=>$chat->write(1,$act('resolve',1)),'Opening or delivery cannot resolve an unanswered question');
$chat->write(2,$act('later',1));
check($chat->prompt(2)['count']===2&&count($chat->prompt(2)['incoming'])===1,'Respond Later suppresses popup but keeps pending count');
denied(fn()=>$chat->write(2,$act('reply',2)+['request_key'=>S::uuid(),'message'=>'  ']),'A written reply is required');
$replyData=$act('reply',2)+['message'=>'Two boxes','request_key'=>S::uuid()];
$chat->write(2,$replyData);$chat->write(2,$replyData);
check($chat->prompt(1)['count']===1&&count($chat->detail(1,$cid)['messages'])===2,'One reply notifies the owner in the same thread');
$chat->write(1,$act('reply',3)+['message'=>'What size?','request_key'=>S::uuid()]);
denied(fn()=>$chat->write(1,$act('resolve',3)),'A stale view cannot resolve a follow-up');
$chat->write(2,$act('reply',4)+['message'=>'Large','request_key'=>S::uuid()]);
denied(fn()=>$chat->write(2,$act('resolve',5)),'Employee cannot resolve on owner’s behalf');
$chat->write(1,$act('resolve',5));
check($chat->detail(2,$cid)['state']==='completed'&&count($chat->detail(2,$cid)['messages'])===4,'Explicit resolution retains entire conversation');
check($chat->detail(2,$other)['state']==='employee'&&count($s->listing(2)['records'])===$before,'Independent threads leave ordinary acknowledgment totals unchanged');
check(!$box->register(5)&&!$box->register(3),'Other accounts cannot enumerate private assistance or reports');
check(in_array('report',array_column($box->register(1),'kind'),true)&&in_array('assistance',array_column($box->register(1),'kind'),true),'Designated owner register includes both existing mailbox types');
$ask=$chat->write(1,array_replace($start,['request_key'=>S::uuid()]))['id'];
$answer=['operation'=>'reply','id'=>$ask,'revision'=>1,'message'=>'Response','request_key'=>S::uuid()];
$chat->write(2,$answer);
$remove=['operation'=>'remove','id'=>$ask,'revision'=>2];
denied(fn()=>$chat->write(2,$remove),'Employee cannot delete a response chat');
denied(fn()=>$chat->write(5,$remove),'Another admin cannot delete this response chat');
$secondary=$chat->write(5,array_replace($start,['request_key'=>S::uuid()]))['id'];
check(!$chat->detail(5,$secondary)['can_remove'],'Other admins do not see Delete even in their own threads');
denied(fn()=>$chat->write(5,['operation'=>'remove','id'=>$secondary,'revision'=>1]),'Another admin cannot delete even their own thread');
$chat->write(1,$remove);$chat->write(1,$remove);
check(!in_array($ask,array_column($chat->listing(1),'id'))&&!$chat->prompt(1)['count'],'Removed response chat no longer appears or prompts the owner');
check(in_array($ask,array_column($chat->listing(2),'id'))&&count($chat->detail(2,$ask)['messages'])===2,'Owner removal leaves the employee copy and history unchanged');
$chat->write(2,array_replace($answer,['revision'=>2,'message'=>'Another detail','request_key'=>S::uuid()]));
check($chat->prompt(1)['count']===1,'New employee response reopens owner visibility');
denied(fn()=>$chat->write(1,$remove),'Stale delete cannot hide a newer response');
$last=(int)$box->inbox(1,2)['threads'][0]['latest'];
denied(fn()=>$box->removeFromInbox(2,2,$last),'Employee cannot remove private assistance from owner inbox');
denied(fn()=>$box->removeFromInbox(5,2,$last),'Another admin cannot remove private assistance');
$history=$box->inbox(2)['messages'];$box->removeFromInbox(1,2,$last);$box->removeFromInbox(1,2,$last);
check(!$box->inbox(1)['threads']&&!$box->awaitingReply(1)&&!$box->pendingPrompt(1)&&!$box->attention(1)['private'],'Private assistance deletion clears only the owner list, queue and reminders');
check($history===$box->inbox(2)['messages']&&$box->inbox(1)['reports'],'Employee history and anonymous reports remain intact');
$box->send(2,['message'=>'New question','request_key'=>S::uuid()]);
check(count($box->inbox(1)['threads'])===1&&$box->attention(1)['private']===1,'New assistance message returns to owner inbox');
denied(fn()=>$box->removeFromInbox(1,2,$last),'Stale assistance delete cannot hide new message');
